##############################################################################
# 11Nechako_drought_manuscript1_current.R
#
# CURRENT-MANUSCRIPT VERSION
#
# PM-vs-ERA5-Land native potential-evaporation SPEI differences are treated as
# PET-product/formulation sensitivity, not as an additive physical decomposition.
#
# Legacy Sections 1 and 3 are retained only as disabled guards; obsolete
# PET/decomposition outputs are not generated by this manuscript script. Current Results should come from scripts 9, 10b, 12, 13, 15, and 16.
##############################################################################

RUN_LEGACY_OUTPUTS <- FALSE

# ==============================================================================
# WORKING-DIRECTORY SETUP
# ==============================================================================
# The manuscript script is intentionally runnable as a standalone reporting
# stage. Upstream scientific calculations remain in their dedicated scripts.
WD_PATH <- Sys.getenv(
  "NECHAKO_WD",
  unset = "D:/Nechako_Drought/Nechako/"
)
if (!dir.exists(WD_PATH)) {
  stop("Working directory not found: ", WD_PATH)
}
setwd(WD_PATH)

# ==============================================================================
# LEGACY SECTION 1 — DISABLED FOR CURRENT MANUSCRIPT
# ==============================================================================
# The former temperature-only PET sensitivity residual plot is retired.
# Current PET-product sensitivity is handled by scripts 10b, 12, and 13 using
# FAO-56 Penman–Monteith PET versus ERA5-Land native potential evaporation.
# ==============================================================================
if (isTRUE(RUN_LEGACY_OUTPUTS)) {
  stop("Legacy PET-formulation residual outputs are retired; use the ERA5-Land potential-evaporation workflow.")
} else {
  cat("\n[SKIP] Legacy Section 1 disabled: obsolete PET-formulation residual output is retired.\n")
}

# ==============================================================================
# SECTION 2 — AUTHORITATIVE SW08 EVENT-RANKING RESULTS
# ==============================================================================
# SOURCE: 9event_ranking.R
# PURPOSE: The manuscript script is a reporting/assembly stage. It MUST NOT
#          re-implement the event detector or recompute event severity.
#          9event_ranking.R is authoritative for the SW08 catalog, duration
#          classes, return periods, recent-event ranking, and Kendall RP.
#
# CURRENT EVENT DEFINITION (implemented in script 9):
#   onset/termination : single threshold x < -0.5 / x >= -0.5
#   hysteresis        : none
#   intensity         : mean(-0.5 - x_t) over event months
#   severity          : intensity × duration
#   minimum duration  : accumulation scale k (1, 3, 6, 12, 24, 36 months)
#   record            : 1950-2025
#   recent period     : 2022-2025
#
# OUTPUTS WRITTEN HERE:
#   temporal_drought/Table_MS_SW08_event_summary.csv
#   temporal_drought/Table_MS_SW08_recent_primary_events.csv
#   temporal_drought/Table_MS_SW08_duration_class_RP.csv
#   temporal_drought/Table_MS_KendallRP_recent_primary.csv
#   temporal_drought/Table_MS_KendallRP_multiindex.csv
#   temporal_drought/Table_MS_event_definition_comparison.csv
# ==============================================================================

suppressPackageStartupMessages({
  library(data.table)
  library(dplyr)
})

cat("\
============================================================\
")
cat(" SECTION 2: AUTHORITATIVE SW08 EVENT-RANKING RESULTS\
")
cat("            Source = 9event_ranking.R\
")
cat("============================================================\
\
")

RANKING_DIR <- file.path(WD_PATH, "temporal_drought", "event_ranking")
TREND_DIR   <- file.path(WD_PATH, "temporal_drought")

if (!dir.exists(RANKING_DIR))
  stop("Event-ranking directory not found: ", RANKING_DIR,
       "\
Run 9event_ranking.R before 11nechako_drought_manuscript.R.")

read_required_csv <- function(path, label = basename(path)) {
  if (!file.exists(path))
    stop("Required manuscript input is missing: ", path,
         "\
Run 9event_ranking.R first.")
  x <- data.table::fread(path)
  if (!nrow(x)) stop("Required manuscript input is empty: ", path)
  x
}

# ---- 2.1 Full SW08 catalog: authoritative event population -----------------
sw08_catalog <- read_required_csv(
  file.path(RANKING_DIR, "ranked_event_catalog_SW08.csv")
)

required_catalog <- c(
  "index_label", "start_date", "end_date", "start_year",
  "duration_months", "duration_class", "mean_int", "severity",
  "rank_by_severity", "return_period_years", "percentile_rank", "is_recent"
)
missing_catalog <- setdiff(required_catalog, names(sw08_catalog))
if (length(missing_catalog))
  stop("ranked_event_catalog_SW08.csv is missing: ",
       paste(missing_catalog, collapse = ", "))

sw08_catalog[, `:=`(
  start_date = as.Date(start_date),
  end_date = as.Date(end_date),
  start_year = as.integer(start_year),
  duration_months = as.integer(duration_months),
  mean_int = as.numeric(mean_int),
  severity = as.numeric(severity),
  rank_by_severity = as.integer(rank_by_severity),
  return_period_years = as.numeric(return_period_years),
  percentile_rank = as.numeric(percentile_rank),
  is_recent = as.logical(is_recent)
)]

# Restrict manuscript-facing event population to the common manuscript scales
# and current observed indices. Legacy Thornthwaite products are not part of
# the current SPEI framework even if auxiliary files exist in RANKING_DIR.
sw08_catalog_ms <- sw08_catalog[
  grepl("^(spi|spei|spei_era5)_", index_label) &
    as.integer(sub(".*_([0-9]+)$", "\\1", index_label)) %in%
    c(1L, 3L, 6L, 12L, 24L, 36L)
]

# ---- 2.2 Manuscript event summary ------------------------------------------
# One row per index/scale: number of qualifying SW08 events, most severe
# historical event, and most severe recent event. No event statistics are
# recomputed; all values originate in script 9's ranked catalog.
if (nrow(sw08_catalog_ms)) {
  event_summary <- sw08_catalog_ms |>
    as.data.frame() |>
    mutate(
      index = case_when(
        grepl("^spei_era5_", index_label) ~ "SPEI-ERA5",
        grepl("^spei_", index_label) ~ "SPEI-PM",
        grepl("^spi_", index_label) ~ "SPI",
        TRUE ~ index_label
      ),
      scale_months = as.integer(sub(".*_([0-9]+)$", "\\1", index_label))
    ) |>
    group_by(index, scale_months) |>
    summarise(
      n_qualifying_events = n(),
      historical_max_severity = max(severity, na.rm = TRUE),
      historical_max_severity_start = format(start_date[which.max(severity)], "%Y-%m"),
      historical_max_severity_end = format(end_date[which.max(severity)], "%Y-%m"),
      recent_n_events = sum(is_recent, na.rm = TRUE),
      recent_max_severity = ifelse(any(is_recent), max(severity[is_recent], na.rm = TRUE), NA_real_),
      recent_max_start = ifelse(any(is_recent), format(start_date[is_recent][which.max(severity[is_recent])], "%Y-%m"), NA_character_),
      recent_max_end = ifelse(any(is_recent), format(end_date[is_recent][which.max(severity[is_recent])], "%Y-%m"), NA_character_),
      .groups = "drop"
    ) |>
    arrange(index, scale_months)
} else {
  event_summary <- data.frame()
}

write.csv(
  event_summary,
  file.path(TREND_DIR, "Table_MS_SW08_event_summary.csv"),
  row.names = FALSE
)

# ---- 2.3 Recent primary events ---------------------------------------------
recent_primary <- sw08_catalog_ms[is_recent == TRUE & rank_by_severity == 1L]
if (nrow(recent_primary)) {
  recent_primary <- as.data.frame(recent_primary) |>
    mutate(
      index = case_when(
        grepl("^spei_era5_", index_label) ~ "SPEI-ERA5",
        grepl("^spei_", index_label) ~ "SPEI-PM",
        grepl("^spi_", index_label) ~ "SPI",
        TRUE ~ index_label
      ),
      scale_months = as.integer(sub(".*_([0-9]+)$", "\\1", index_label))
    ) |>
    arrange(index, scale_months)
}

write.csv(
  recent_primary,
  file.path(TREND_DIR, "Table_MS_SW08_recent_primary_events.csv"),
  row.names = FALSE
)

# ---- 2.4 Duration-class return periods -------------------------------------
rp_file <- file.path(RANKING_DIR, "return_period_by_duration_class_SW08.csv")
if (file.exists(rp_file)) {
  rp_ms <- data.table::fread(rp_file) |>
    as.data.frame() |>
    filter(grepl("^(spi|spei|spei_era5)_", index_label, ignore.case = TRUE)) |>
    mutate(
      index = case_when(
        grepl("^SPEI_ERA5_", index_label) ~ "SPEI-ERA5",
        grepl("^SPEI_", index_label) ~ "SPEI-PM",
        grepl("^SPI_", index_label) ~ "SPI",
        TRUE ~ index_label
      )
    )
  write.csv(rp_ms, file.path(TREND_DIR, "Table_MS_SW08_duration_class_RP.csv"), row.names = FALSE)
} else {
  rp_ms <- data.frame()
  cat("  [SKIP] SW08 duration-class RP table not found.\
")
}

# ---- 2.5 Kendall return periods: recent primary event by scale -------------
kendall_primary_file <- file.path(
  RANKING_DIR, "Table_KendallRP_Recent_Primary_AllScales.csv"
)
if (file.exists(kendall_primary_file)) {
  kendall_primary <- data.table::fread(kendall_primary_file) |>
    as.data.frame() |>
    mutate(
      index = case_when(
        grepl("^spei_era5_", index_label) ~ "SPEI-ERA5",
        grepl("^spei_", index_label) ~ "SPEI-PM",
        grepl("^spi_", index_label) ~ "SPI",
        TRUE ~ index_label
      )
    ) |>
    arrange(index, scale_months)
  
  write.csv(
    kendall_primary,
    file.path(TREND_DIR, "Table_MS_KendallRP_recent_primary.csv"),
    row.names = FALSE
  )
} else {
  kendall_primary <- data.frame()
  cat("  [SKIP] Recent-primary Kendall RP table not found.\
")
}

# ---- 2.6 Kendall multi-index comparison ------------------------------------
kendall_multi_file <- file.path(RANKING_DIR, "Table_KendallRP_MultiIndex.csv")
if (file.exists(kendall_multi_file)) {
  kendall_multi <- data.table::fread(kendall_multi_file) |>
    as.data.frame()
  write.csv(
    kendall_multi,
    file.path(TREND_DIR, "Table_MS_KendallRP_multiindex.csv"),
    row.names = FALSE
  )
} else {
  kendall_multi <- data.frame()
  cat("  [SKIP] Multi-index Kendall RP table not found.\
")
}

# ---- 2.7 Definition-sensitivity comparison: SW08 vs legacy hysteresis -------
hyst_file <- file.path(RANKING_DIR, "Table_SW08_vs_Hyst_Comparison.csv")
if (file.exists(hyst_file)) {
  hyst_compare <- data.table::fread(hyst_file) |>
    as.data.frame()
  write.csv(
    hyst_compare,
    file.path(TREND_DIR, "Table_MS_event_definition_comparison.csv"),
    row.names = FALSE
  )
} else {
  hyst_compare <- data.frame()
  cat("  [SKIP] SW08-vs-hysteresis comparison not found.\
")
}

cat(sprintf("  ✓ Loaded authoritative SW08 catalog: %d events\
", nrow(sw08_catalog_ms)))
cat("  ✓ Manuscript event summary written.\
")
cat("  ✓ Recent primary-event table written.\
")

# ==============================================================================
# LEGACY SECTION 3 — DISABLED FOR CURRENT MANUSCRIPT
# ==============================================================================
# The former thermodynamic/dynamic decomposition and its manuscript blank
# extractor are retired. The current framework treats PM versus ERA5-Land
# native potential evaporation as PET-product/formulation sensitivity.
# ==============================================================================
if (isTRUE(RUN_LEGACY_OUTPUTS)) {
  stop("Legacy thermodynamic/dynamic decomposition outputs are retired; use scripts 10b, 12, and 13.")
} else {
  cat("\n[SKIP] Legacy Section 3 disabled: obsolete thermodynamic/dynamic decomposition is retired.\n")
}

# ==============================================================================
# SECTION 4 — FIGURE: Seasonal Cycle of Precipitation and PM-PET
# ==============================================================================
# SOURCE: 16_climatology_water_budget.R authoritative monthly climatology
# PURPOSE: Two-panel bar chart: (a) mean monthly P vs PM-PET, (b) P - PM-PET
# DATA:    climatology_monthly_1950_2025.csv
# OUTPUT:  FigS_Seasonality_P_PET.pdf + .png in BASIN_PLOT_DIR
#
# IMPORTANT:
#   Do NOT use spi_01_basin_average.csv here. That file contains SPI-1 values,
#   not precipitation depth. The previous version therefore produced an invalid
#   precipitation total and aridity index.
# ==============================================================================

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(patchwork)
  library(data.table)
})

cat("\n============================================================\n")
cat("  SECTION 4: FIGURE — Seasonal Cycle of P and PM-PET\n")
cat("============================================================\n\n")

BASIN_PLOT_DIR <- file.path(WD_PATH, "temporal_drought", "basin_averaged_plots")
WB_DIR_4       <- file.path(WD_PATH, "temporal_drought", "climatology_water_budget")
CLIM_CSV_4     <- file.path(WB_DIR_4, "climatology_monthly_1950_2025.csv")

dir.create(BASIN_PLOT_DIR, showWarnings = FALSE, recursive = TRUE)

MON_LABELS <- month.abb

if (!file.exists(CLIM_CSV_4)) {
  stop(
    "Authoritative monthly climatology not found: ", CLIM_CSV_4,
    "\n  Run 16_climatology_water_budget.R first."
  )
}

clim_4 <- data.table::fread(CLIM_CSV_4) |>
  as.data.frame()

required_clim_4 <- c(
  "month", "precipitation_mm", "PET_PM_mm", "temperature_degC"
)
missing_clim_4 <- setdiff(required_clim_4, names(clim_4))
if (length(missing_clim_4)) {
  stop(
    "Monthly climatology is missing required column(s): ",
    paste(missing_clim_4, collapse = ", ")
  )
}

# Select the authoritative whole-basin row where the file contains multiple
# regional rows.
if (all(c("region_id", "region_name") %in% names(clim_4))) {
  target_id_4 <- Sys.getenv("NECHAKO_BASIN_REGION_ID", unset = "")
  
  if (nzchar(target_id_4) && target_id_4 %in% unique(clim_4$region_id)) {
    clim_4 <- clim_4[clim_4$region_id == target_id_4, , drop = FALSE]
  } else {
    exact_basin_4 <- unique(
      clim_4[
        grepl(
          "^(Nechako River Basin|Nechako Basin|Whole Nechako Basin|Entire Nechako Basin)$",
          trimws(clim_4$region_name),
          ignore.case = TRUE
        ),
        c("region_id", "region_name")
      ]
    )
    
    if (nrow(exact_basin_4) == 1L) {
      clim_4 <- clim_4[
        clim_4$region_id == exact_basin_4$region_id[1],
        ,
        drop = FALSE
      ]
    } else if (data.table::uniqueN(clim_4$region_id) > 1L) {
      stop(
        "Cannot unambiguously identify the whole-basin row in ",
        CLIM_CSV_4,
        ". Set NECHAKO_BASIN_REGION_ID."
      )
    }
  }
}

clim_4$month <- as.integer(clim_4$month)
clim_4$precipitation_mm <- as.numeric(clim_4$precipitation_mm)
clim_4$PET_PM_mm <- as.numeric(clim_4$PET_PM_mm)

if (nrow(clim_4) != 12L || !setequal(clim_4$month, 1:12)) {
  stop(
    "Expected exactly 12 calendar-month climatology rows for the whole basin; found ",
    nrow(clim_4), "."
  )
}

cm_all_4 <- clim_4 |>
  arrange(month) |>
  transmute(
    month,
    month_lab = factor(MON_LABELS[month], levels = MON_LABELS),
    precipitation_mm,
    PET_PM_mm
  )

cat(sprintf(
  "  1950-2025 climatology: mean annual P = %.1f mm; mean annual PM-PET = %.1f mm\n",
  sum(cm_all_4$precipitation_mm, na.rm = TRUE),
  sum(cm_all_4$PET_PM_mm, na.rm = TRUE)
))
cat(sprintf(
  "  PET/P ratio = %.3f\n",
  sum(cm_all_4$PET_PM_mm, na.rm = TRUE) /
    sum(cm_all_4$precipitation_mm, na.rm = TRUE)
))

# ── 4.1: Panel (a) — grouped bar chart P vs PM-PET ---------------------------
cm_plot_4 <- bind_rows(
  cm_all_4 |>
    transmute(
      month, month_lab, mean_val = precipitation_mm,
      variable = "Precipitation (P)"
    ),
  cm_all_4 |>
    transmute(
      month, month_lab, mean_val = PET_PM_mm,
      variable = "PM-PET"
    )
)

COL_P   <- "#4393c3"
COL_PET <- "#d7301f"

cm_plot_4$variable <- factor(
  cm_plot_4$variable,
  levels = c("Precipitation (P)", "PM-PET")
)

p_seas1 <- ggplot(
  cm_plot_4,
  aes(x = month_lab, y = mean_val, fill = variable, group = variable)
) +
  geom_col(
    position = position_dodge(0.72),
    width = 0.65, colour = "white", linewidth = 0.15
  ) +
  scale_fill_manual(
    values = c("Precipitation (P)" = COL_P, "PM-PET" = COL_PET),
    name = NULL
  ) +
  scale_y_continuous(
    name = expression(mm~month^{-1}),
    expand = expansion(mult = c(0, 0.09))
  ) +
  labs(
    title = "(a) Mean monthly precipitation and Penman–Monteith PET",
    subtitle = paste0(
      "1950–2025 calendar-month climatology | Annual totals: P = ",
      round(sum(cm_all_4$precipitation_mm)), " mm; PM-PET = ",
      round(sum(cm_all_4$PET_PM_mm)), " mm"
    ),
    x = NULL
  ) +
  theme_classic(base_size = 9.5) +
  theme(
    legend.position = c(0.86, 0.88),
    legend.background = element_rect(fill = "white", colour = NA),
    legend.text = element_text(size = 8.5),
    legend.key.size = unit(0.40, "cm"),
    plot.title = element_text(size = 9.5, face = "bold"),
    plot.subtitle = element_text(size = 7.5, colour = "grey40"),
    axis.text = element_text(size = 8.5),
    axis.title.y = element_text(size = 8.5),
    panel.grid.major.y = element_line(colour = "grey90", linewidth = 0.3),
    plot.margin = margin(4, 6, 2, 4)
  )

# ── 4.2: Panel (b) — climatic water balance P − PM-PET -----------------------
cm_wb_4 <- cm_all_4 |>
  mutate(
    wb = precipitation_mm - PET_PM_mm,
    fill_col = ifelse(wb >= 0, COL_P, COL_PET)
  )

p_seas2 <- ggplot(cm_wb_4, aes(x = month_lab, y = wb, fill = fill_col)) +
  geom_col(colour = "white", linewidth = 0.15, width = 0.65) +
  geom_hline(yintercept = 0, colour = "grey30", linewidth = 0.55) +
  scale_fill_identity() +
  scale_y_continuous(
    name = expression(P - PET[PM]~~(mm~month^{-1})),
    expand = expansion(mult = c(0.12, 0.10))
  ) +
  labs(
    title = "(b) Climatic water balance P − PM-PET",
    subtitle = "Positive values indicate P > PM-PET; negative values indicate PM-PET > P",
    x = "Calendar month"
  ) +
  theme_classic(base_size = 9.5) +
  theme(
    plot.title = element_text(size = 9.5, face = "bold"),
    plot.subtitle = element_text(size = 7.5, colour = "grey40"),
    axis.text = element_text(size = 8.5),
    axis.title.y = element_text(size = 8.5),
    panel.grid.major.y = element_line(colour = "grey90", linewidth = 0.3),
    plot.margin = margin(2, 6, 4, 4)
  )

# ── 4.3: Assemble and save ---------------------------------------------------
fig_seas <- p_seas1 / p_seas2 +
  plot_annotation(
    title = paste0(
      "Nechako River Basin — Seasonal cycle of precipitation ",
      "and Penman–Monteith PET"
    ),
    subtitle = paste0(
      "1950–2025 calendar-month climatology. Annual totals: P = ",
      round(sum(cm_all_4$precipitation_mm)), " mm; PM-PET = ",
      round(sum(cm_all_4$PET_PM_mm)), " mm; PET/P = ",
      round(sum(cm_all_4$PET_PM_mm) / sum(cm_all_4$precipitation_mm), 3), "."
    ),
    theme = theme(
      plot.title = element_text(size = 11, face = "bold", hjust = 0),
      plot.subtitle = element_text(
        size = 8.5, colour = "grey35", hjust = 0,
        margin = margin(b = 4)
      )
    )
  )

cat("\n── Saving FigS_Seasonality_P_PET...\n")
for (ext in c("pdf", "png")) {
  out_f <- file.path(
    BASIN_PLOT_DIR,
    paste0("FigS_Seasonality_P_PET.", ext)
  )
  tryCatch(
    ggsave(
      out_f, fig_seas,
      width = 7.2, height = 7.0, units = "in",
      dpi = if (ext == "png") 300 else "print",
      device = ext
    ),
    error = function(e) cat(sprintf("  ⚠ %s: %s\n", ext, e$message))
  )
  cat(sprintf("  ✓ %s\n", basename(out_f)))
}
cat(sprintf(
  "\n✓ Section 4 complete.\n  Output: %s\n",
  normalizePath(BASIN_PLOT_DIR)
))

# ============================================================================== 
# SECTION 5 — CURRENT MANUSCRIPT FIGURE/TABLE: PET-FORMULATION AGREEMENT
# ============================================================================== 
# SOURCE: 12PET_formulation_sensitivity_v2.R
# PURPOSE: Add a compact, manuscript-ready figure and machine-readable table
#          summarising full-record and drought-active PET-formulation agreement.
# OUTPUTS:
#   pet_sensitivity/Fig_MS_PET_formulation_agreement.pdf/.png
#   pet_sensitivity/Table_MS_PET_formulation_agreement.csv
# ============================================================================== 

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
  library(tidyr)
  library(data.table)
  library(patchwork)
})

PET_SENS_DIR <- file.path(WD_PATH, "pet_sensitivity")
PET_AGREE_CSV <- file.path(PET_SENS_DIR, "PET_agreement_by_scale_period.csv")

if (file.exists(PET_AGREE_CSV)) {
  cat("\n============================================================\n")
  cat("  SECTION 5: PET-FORMULATION AGREEMENT FIGURE/TABLE\n")
  cat("============================================================\n\n")
  
  agree <- data.table::fread(PET_AGREE_CSV)
  names(agree) <- tolower(names(agree))
  
  required <- c("scale", "period", "pearson_r", "rmse",
                "drought_state_agreement_pct", "mean_abs_delta_spei")
  miss <- setdiff(required, names(agree))
  if (length(miss)) {
    stop("PET agreement table is missing required column(s): ",
         paste(miss, collapse = ", "))
  }
  
  agree$scale <- as.integer(agree$scale)
  agree <- agree |>
    filter(scale %in% c(1L, 3L, 6L, 12L, 24L, 36L))
  
  keep_periods <- c("Full record", "Drought-active")
  agree_plot <- agree |>
    filter(period %in% keep_periods) |>
    select(scale, period, pearson_r, rmse,
           drought_state_agreement_pct, mean_abs_delta_spei) |>
    pivot_longer(
      cols = c(pearson_r, rmse, drought_state_agreement_pct, mean_abs_delta_spei),
      names_to = "metric", values_to = "value"
    ) |>
    mutate(
      metric = factor(
        metric,
        levels = c("pearson_r", "rmse", "drought_state_agreement_pct", "mean_abs_delta_spei"),
        labels = c("Pearson r", "RMSE", "Drought-state agreement (%)", "Mean |ΔSPEI|")
      ),
      period = factor(period, levels = keep_periods)
    )
  
  p_agree <- ggplot(agree_plot,
                    aes(x = scale, y = value, group = period, linetype = period)) +
    geom_line(linewidth = 0.55) +
    geom_point(size = 1.9) +
    facet_wrap(~ metric, scales = "free_y", ncol = 2) +
    scale_x_continuous(breaks = c(1, 3, 6, 12, 24, 36)) +
    labs(
      x = "Accumulation scale (months)",
      y = NULL,
      linetype = NULL,
      title = "PET-formulation agreement across drought timescales",
      subtitle = "Independent SPEI-PM and SPEI-ERA5L standardization; drought-active months use the common −0.5 threshold"
    ) +
    theme_bw(base_size = 10) +
    theme(
      legend.position = "bottom",
      strip.text = element_text(face = "bold"),
      panel.grid.minor = element_blank()
    )
  
  for (ext in c("pdf", "png")) {
    ggsave(
      file.path(PET_SENS_DIR, paste0("Fig_MS_PET_formulation_agreement.", ext)),
      p_agree,
      width = 8.2,
      height = 6.2,
      units = "in",
      dpi = if (ext == "png") 300 else "print",
      device = ext
    )
  }
  
  table_agree <- agree |>
    filter(period %in% keep_periods) |>
    arrange(scale, period) |>
    mutate(
      pearson_r = round(pearson_r, 4),
      rmse = round(rmse, 4),
      drought_state_agreement_pct = round(drought_state_agreement_pct, 2),
      mean_abs_delta_spei = round(mean_abs_delta_spei, 4)
    )
  
  write.csv(
    table_agree,
    file.path(PET_SENS_DIR, "Table_MS_PET_formulation_agreement.csv"),
    row.names = FALSE
  )
  
  cat("  ✓ PET-formulation agreement figure/table written.\n")
} else {
  cat("\n[SKIP] Section 5: PET_agreement_by_scale_period.csv not found.\n")
}

# ============================================================================== 
# SECTION 6 — CURRENT MANUSCRIPT TABLE: RECENT DROUGHT MINIMA ACROSS SCALES
# ==============================================================================
# PURPOSE: Extract the actual 2022–2025 basin-average minima used to describe
#          acute severity and longer-timescale persistence.
#
# IMPORTANT:
#   The previous version searched the full 1950–2025 record, which could return
#   a historical minimum rather than a 2022–2025 minimum. This section now
#   explicitly restricts the series to 2022-01 through 2025-12.
#
# OUTPUT:
#   temporal_drought/Table_MS_recent_drought_minima.csv
#   temporal_drought/Table_MS_recent_drought_minima_all_scales.csv
# ============================================================================== 

find_basin_series <- function(index_keys, scale = 3L) {
  candidate_dirs <- c(
    file.path(WD_PATH, "temporal_drought", "basin_averaged_timeseries"),
    file.path(WD_PATH, "temporal_drought", "basin_averaged_timeseries_era5land")
  )
  
  for (d in candidate_dirs) {
    if (!dir.exists(d)) next
    
    files <- list.files(d, full.names = TRUE)
    
    for (key in index_keys) {
      hit <- files[grepl(
        sprintf("^%s_%02d_basin_average\\.csv$", key, scale),
        basename(files), ignore.case = TRUE
      )]
      
      if (length(hit)) {
        df <- tryCatch(
          data.table::fread(hit[1]),
          error = function(e) NULL
        )
        
        if (!is.null(df) && all(c("date", "value") %in% names(df))) {
          df$date <- as.Date(df$date)
          df$value <- as.numeric(df$value)
          
          return(
            df[
              is.finite(df$value) &
                df$date >= as.Date("2022-01-01") &
                df$date <= as.Date("2025-12-01"),
              c("date", "value")
            ]
          )
        }
      }
    }
  }
  
  NULL
}

make_minimum_row <- function(index_label, index_keys, scale) {
  ts <- find_basin_series(index_keys, scale)
  
  if (is.null(ts) || !nrow(ts)) {
    return(data.frame(
      scale = as.integer(scale),
      index = index_label,
      minimum_value = NA_real_,
      minimum_period = NA_character_,
      stringsAsFactors = FALSE
    ))
  }
  
  i <- which.min(ts$value)
  
  data.frame(
    scale = as.integer(scale),
    index = index_label,
    minimum_value = round(ts$value[i], 4),
    minimum_period = format(ts$date[i], "%b %Y"),
    stringsAsFactors = FALSE
  )
}

MINIMA_SCALES <- c(1L, 3L, 6L, 12L, 24L, 36L)

MINIMA_TABLE <- do.call(
  rbind,
  c(
    list(
      do.call(
        rbind,
        lapply(
          MINIMA_SCALES,
          function(sc) make_minimum_row("SPI", c("spi"), sc)
        )
      )
    ),
    list(
      do.call(
        rbind,
        lapply(
          MINIMA_SCALES,
          function(sc) make_minimum_row("SPEI-PM", c("spei"), sc)
        )
      )
    ),
    list(
      do.call(
        rbind,
        lapply(
          MINIMA_SCALES,
          function(sc) make_minimum_row(
            "SPEI-ERA5L",
            c("spei_era5", "spei_era5land"),
            sc
          )
        )
      )
    )
  )
)

