# SECTION 10 — MANUSCRIPT WATER-BUDGET FIGURE: P − AET AND AET/P
# ============================================================================== 
# PURPOSE: Replace the previous four-panel anomaly figure with a compact
#          manuscript figure showing the two land-surface water-budget
#          diagnostics used explicitly in Results 3c:
#            (a) P − AET  : monthly residual water balance (mm month-1)
#            (b) AET/P    : fraction of monthly precipitation represented by AET
#
# DATA SOURCE:
#   16_climatology_water_budget.R
#   temporal_drought/climatology_water_budget/
#     recent_2022_2025_monthly_climate_water_budget.csv
#
# IMPORTANT:
#   P − AET is retained as a water-budget residual diagnostic and is NOT
#   interpreted as observed runoff or actual water availability. The AET/P
#   ratio is shown as a diagnostic of the relationship between precipitation
#   supply and actual evapotranspiration. AET is ERA5-Land total evaporation
#   and is never inferred from PET.
#
# OUTPUT:
#   temporal_drought/Fig_MS_water_budget_diagnostics.pdf
#   temporal_drought/Fig_MS_water_budget_diagnostics.png
# ============================================================================== 

suppressPackageStartupMessages({
  library(ggplot2)
  library(dplyr)
})

WB_FIG_DIR_10 <- file.path(WD_PATH, "temporal_drought")
WB_MONTHLY_FILE_10 <- file.path(
  WB_DIR,
  "recent_2022_2025_monthly_climate_water_budget.csv"
)

if (!file.exists(WB_MONTHLY_FILE_10)) {
  stop(
    "Authoritative monthly water-budget file not found: ",
    WB_MONTHLY_FILE_10,
    "\nRun 16_climatology_water_budget.R before running 11nechako_drought_manuscript.R."
  )
}

wb_monthly_10 <- data.table::fread(WB_MONTHLY_FILE_10) |>
  as.data.frame()

required_wb_10 <- c(
  "region_id",
  "region_name",
  "year",
  "month",
  "precip_mm_month",
  "aet_mm_month",
  "AET_over_P"
)
missing_wb_10 <- setdiff(required_wb_10, names(wb_monthly_10))
if (length(missing_wb_10)) {
  stop(
    "Authoritative monthly water-budget file is missing required column(s): ",
    paste(missing_wb_10, collapse = ", ")
  )
}

# ------------------------------------------------------------------------------
# 10.1 Select the whole-basin 2022–2025 monthly series.
# ------------------------------------------------------------------------------
target_basin_id_10 <- Sys.getenv(
  "NECHAKO_BASIN_REGION_ID",
  unset = "Nechako_Basin"
)

if (!(target_basin_id_10 %in% unique(wb_monthly_10$region_id))) {
  basin_candidates_10 <- unique(
    wb_monthly_10[
      grepl(
        "^(Nechako Basin|Nechako River Basin|Whole Nechako Basin|Entire Nechako Basin)$",
        trimws(wb_monthly_10$region_name),
        ignore.case = TRUE
      ),
      c("region_id", "region_name")
    ]
  )
  
  if (nrow(basin_candidates_10) == 1L) {
    target_basin_id_10 <- basin_candidates_10$region_id[1]
  } else {
    stop(
      "Whole-basin series could not be identified in the authoritative monthly " ,
      "water-budget file. Set NECHAKO_BASIN_REGION_ID explicitly."
    )
  }
}

# Collapse duplicate region-year-month rows only when duplicate finite values
# are identical. Conflicting values are treated as an upstream data error.
unique_finite_10 <- function(x, label) {
  x <- as.numeric(x)
  x <- x[is.finite(x)]
  if (!length(x)) return(NA_real_)
  if (length(x) == 1L) return(x[1])
  if (max(x) - min(x) <= 1e-10) return(x[1])
  stop(
    "Conflicting finite values found for ", label,
    " within a single region-year-month group."
  )
}

wb_fig_source_10 <- wb_monthly_10 |>
  filter(
    region_id == target_basin_id_10,
    year >= 2022L,
    year <= 2025L
  ) |>
  mutate(
    year = as.integer(year),
    month = as.integer(month),
    precip_mm_month = as.numeric(precip_mm_month),
    aet_mm_month = as.numeric(aet_mm_month),
    AET_over_P = as.numeric(AET_over_P)
  ) |>
  group_by(region_id, region_name, year, month) |>
  summarise(
    precip_mm_month = unique_finite_10(
      precip_mm_month, "precipitation"
    ),
    aet_mm_month = unique_finite_10(
      aet_mm_month, "AET"
    ),
    AET_over_P = unique_finite_10(
      AET_over_P, "AET/P"
    ),
    .groups = "drop"
  ) |>
  mutate(
    date = as.Date(sprintf("%04d-%02d-01", year, month)),
    P_minus_AET_mm = ifelse(
      is.finite(precip_mm_month) & is.finite(aet_mm_month),
      precip_mm_month - aet_mm_month,
      NA_real_
    ),
    AET_over_P_pct = 100 * AET_over_P
  ) |>
  arrange(date)

expected_dates_10 <- seq(
  as.Date("2022-01-01"),
  as.Date("2025-12-01"),
  by = "month"
)

if (!setequal(wb_fig_source_10$date, expected_dates_10) ||
    nrow(wb_fig_source_10) != length(expected_dates_10)) {
  stop(
    "Whole-basin monthly water-budget series does not contain exactly one " ,
    "record for each month from January 2022 through December 2025. Found ",
    nrow(wb_fig_source_10), " monthly records."
  )
}

if (!any(is.finite(wb_fig_source_10$P_minus_AET_mm))) {
  stop("No finite P − AET values are available for the Nechako Basin, 2022–2025.")
}

if (!any(is.finite(wb_fig_source_10$AET_over_P_pct))) {
  stop("No finite AET/P values are available for the Nechako Basin, 2022–2025.")
}

# ------------------------------------------------------------------------------
# 10.2 Plot the two complementary water-budget diagnostics.
# ------------------------------------------------------------------------------
# P − AET is shown as bars because its sign is the principal information:
# positive values indicate P exceeds AET, while negative values indicate AET
# exceeds P. AET/P is shown as a line because it is a bounded ratio diagnostic
# when P is positive; 100% is the direct reference where AET equals P.
p_pmaet_10 <- ggplot(
  wb_fig_source_10,
  aes(x = date, y = P_minus_AET_mm)
) +
  geom_hline(yintercept = 0, linewidth = 0.45) +
  geom_col(width = 20, na.rm = TRUE) +
  scale_x_date(
    date_breaks = "6 months",
    date_labels = "%Y-%m",
    expand = expansion(mult = c(0.005, 0.005))
  ) +
  labs(
    x = NULL,
    y = expression(P - AET~~(mm~month^{-1})),
    title = "(a) Precipitation minus actual evapotranspiration"
  ) +
  theme_classic(base_size = 10) +
  theme(
    axis.text.x = element_blank(),
    axis.ticks.x = element_blank(),
    axis.title.y = element_text(size = 8.8),
    plot.title = element_text(face = "bold", size = 10.5),
    panel.grid.major.y = element_line(colour = "grey90", linewidth = 0.3),
    panel.grid.minor = element_blank(),
    plot.margin = margin(5, 8, 2, 8)
  )

p_aetp_10 <- ggplot(
  wb_fig_source_10,
  aes(x = date, y = AET_over_P_pct)
) +
  geom_hline(yintercept = 100, linetype = "dashed", linewidth = 0.4) +
  geom_line(linewidth = 0.6, na.rm = TRUE) +
  geom_point(size = 1.35, na.rm = TRUE) +
  scale_x_date(
    date_breaks = "6 months",
    date_labels = "%Y-%m",
    expand = expansion(mult = c(0.005, 0.005))
  ) +
  labs(
    x = NULL,
    y = "AET / P (%)",
    title = "(b) Actual evapotranspiration relative to precipitation",
    subtitle = "Dashed line = AET equals precipitation (100%)"
  ) +
