    panel.grid.minor = element_blank(),
    plot.margin = margin(2, 8, 5, 8)
  )

p_wb_diagnostics_10 <- p_pmaet_10 / p_aetp_10 +
  patchwork::plot_annotation(
    title = "Water-budget diagnostics during the 2022–2025 drought",
    subtitle = paste0(
      "Nechako Basin | monthly values, January 2022–December 2025 | ",
      "AET from ERA5-Land total evaporation"
    ),
