      "P − AET is a water-budget residual diagnostic and is not interpreted as observed runoff. ",
      "AET/P expresses actual evapotranspiration relative to precipitation."
    ),
    theme = theme(
      plot.title = element_text(face = "bold", size = 12, hjust = 0),
      plot.subtitle = element_text(size = 8.8, colour = "grey35", hjust = 0),
