      plot.margin = margin(4, 8, 4, 8)
    )
  )

for (ext in c("pdf", "png")) {
  out_f <- file.path(
    WB_FIG_DIR_10,
    paste0("Fig_MS_water_budget_diagnostics.", ext)
  )
  ggplot2::ggsave(
