}

cat(
  "  ✓ Figure contains monthly P − AET and AET/P for the whole Nechako Basin, ",
  "2022–2025.\n",
  sep = ""
)


# ------------------------------------------------------------------------------
# 10.3 Regional companion figures.
# ------------------------------------------------------------------------------
# Produce the same water-budget diagnostics for the seven supplied subbasins,
# while adding the whole-basin series as the FIRST panel of the P − AET figure.
# The regional values are taken directly from the authoritative monthly
# water-budget table generated by Script 16. No new spatial averaging is
# performed here.
#
# Outputs:
#   Fig_MS_water_budget_P_minus_AET_Subbasins_7panel.pdf/.png
#       (filename retained for manuscript continuity; now contains 8 panels:
#        whole basin + 7 subbasins)
#   Fig_MS_water_budget_AET_over_P_Subbasins_7panel.pdf/.png
#       (remains the seven-subbasin companion figure)

wb_subbasin_source_10 <- wb_monthly_10 |>
  filter(
    year >= 2022L,
    year <= 2025L,
    as.character(region_id) != as.character(target_basin_id_10)
  ) |>
  mutate(
    region_id = as.character(region_id),
    region_name = as.character(region_name),
    year = as.integer(year),
    month = as.integer(month),
    precip_mm_month = as.numeric(precip_mm_month),
    aet_mm_month = as.numeric(aet_mm_month),
    AET_over_P = as.numeric(AET_over_P)
  ) |>
  group_by(region_id, region_name, year, month) |>
  summarise(
    precip_mm_month = unique_finite_10(
      precip_mm_month, "subbasin precipitation"
    ),
    aet_mm_month = unique_finite_10(
      aet_mm_month, "subbasin AET"
    ),
    AET_over_P = unique_finite_10(
      AET_over_P, "subbasin AET/P"
    ),
    .groups = "drop"
  ) |>
  mutate(
    date = as.Date(sprintf("%04d-%02d-01", year, month)),
    P_minus_AET_mm = ifelse(
      is.finite(precip_mm_month) & is.finite(aet_mm_month),
      precip_mm_month - aet_mm_month,
      NA_real_
    ),
    AET_over_P_pct = 100 * AET_over_P
  ) |>
  arrange(region_id, date)

subbasin_ids_10 <- unique(wb_subbasin_source_10$region_id)
if (length(subbasin_ids_10) != 7L) {
  stop(
    "Expected exactly 7 supplied subbasins after excluding the whole-basin union; found ",
    length(subbasin_ids_10),
    ". Check the authoritative regional water-budget product."
  )
}

# Stable subbasin panel order: use the authoritative regional catalog when available.
region_catalog_10 <- NULL
region_catalog_file_10 <- file.path(
  WB_DIR,
  "regional",
  "region_catalog.csv"
)

if (file.exists(region_catalog_file_10)) {
  region_catalog_10 <- tryCatch(
    data.table::fread(region_catalog_file_10) |>
      as.data.frame(),
    error = function(e) NULL
  )
}

if (!is.null(region_catalog_10) &&
    all(c("region_id", "region_name") %in% names(region_catalog_10))) {
  catalog_ids_10 <- unique(as.character(region_catalog_10$region_id))
  subbasin_ids_10 <- c(
    catalog_ids_10[catalog_ids_10 %in% subbasin_ids_10],
    setdiff(subbasin_ids_10, catalog_ids_10)
  )
}

region_names_10 <- wb_subbasin_source_10 |>
  distinct(region_id, region_name) |>
  arrange(match(region_id, subbasin_ids_10))

if (anyNA(region_names_10$region_name) ||
    nrow(region_names_10) != length(subbasin_ids_10)) {
  stop("Could not establish a unique region name for every supplied subbasin.")
}

# Whole-basin identity was already validated in Section 10.1. Require exactly
# one whole-basin name before combining it with the seven subbasins.
whole_basin_names_10 <- unique(as.character(wb_fig_source_10$region_name))
if (length(whole_basin_names_10) != 1L || is.na(whole_basin_names_10[1])) {
  stop("Could not establish a unique whole-basin name for the P − AET figure.")
}

# Panel order for the P − AET figure is explicitly:
#   (a) whole basin, followed by (b)–(h) the seven supplied subbasins.
pmaet_panel_ids_10 <- c(
  as.character(target_basin_id_10),
  subbasin_ids_10
)
pmaet_panel_names_10 <- c(
  whole_basin_names_10[1],
  region_names_10$region_name
)
pmaet_panel_labels_10 <- paste0(
  sprintf("(%s) ", letters[seq_along(pmaet_panel_ids_10)]),
  pmaet_panel_names_10
)

if (length(pmaet_panel_ids_10) != 8L ||
    length(pmaet_panel_names_10) != 8L) {
  stop("The P − AET figure must contain exactly 8 panels: whole basin + 7 subbasins.")
}

# Whole-basin data are taken directly from the already validated authoritative
# monthly series; no spatial averaging is performed here.
wb_whole_source_10 <- wb_fig_source_10 |>
  mutate(
    region_id = as.character(target_basin_id_10),
    region_name = whole_basin_names_10[1]
  )

# Keep the existing seven-subbasin source unchanged for the AET/P companion
# figure, and create a separate combined source for the eight-panel P − AET plot.
wb_pmaet_all_10 <- bind_rows(
  wb_whole_source_10 |>
    select(
      region_id, region_name, year, month, date,
      precip_mm_month, aet_mm_month, AET_over_P,
      P_minus_AET_mm, AET_over_P_pct
    ),
  wb_subbasin_source_10 |>
    select(
      region_id, region_name, year, month, date,
      precip_mm_month, aet_mm_month, AET_over_P,
      P_minus_AET_mm, AET_over_P_pct
    )
) |>
  mutate(
    region_label = factor(
      pmaet_panel_labels_10[match(region_id, pmaet_panel_ids_10)],
      levels = pmaet_panel_labels_10
    )
  ) |>
  arrange(match(region_id, pmaet_panel_ids_10), date)

# Add panel labels only to the seven-subbasin AET/P companion figure.
region_labels_10 <- paste0(
  sprintf("(%s) ", letters[seq_along(subbasin_ids_10)]),
  region_names_10$region_name
)

wb_subbasin_source_10 <- wb_subbasin_source_10 |>
  mutate(
    region_label = factor(
      region_labels_10[match(region_id, subbasin_ids_10)],
      levels = region_labels_10
    )
  )

expected_dates_sub_10 <- seq(
  as.Date("2022-01-01"),
  as.Date("2025-12-01"),
  by = "month"
)

coverage_check_sub_10 <- wb_subbasin_source_10 |>
  group_by(region_id) |>
  summarise(
    n_months = n(),
    n_expected_dates = sum(date %in% expected_dates_sub_10),
    .groups = "drop"
  )

if (any(
  coverage_check_sub_10$n_months != length(expected_dates_sub_10) |
  coverage_check_sub_10$n_expected_dates != length(expected_dates_sub_10)
)) {
  bad_ids_10 <- coverage_check_sub_10$region_id[
    coverage_check_sub_10$n_months != length(expected_dates_sub_10) |
      coverage_check_sub_10$n_expected_dates != length(expected_dates_sub_10)
  ]
  stop(
    "One or more supplied subbasins do not contain exactly one monthly water-budget " ,
    "record for every month from January 2022 through December 2025: ",
    paste(bad_ids_10, collapse = ", ")
  )
}

# The whole-basin series was already checked for complete monthly coverage in
# Section 10.1. Require the combined eight-panel source to contain 8 × 48 rows.
if (nrow(wb_pmaet_all_10) != 8L * length(expected_dates_sub_10)) {
  stop(
    "The combined P − AET source does not contain exactly 8 panels × 48 monthly records."
  )
}

if (!any(is.finite(wb_pmaet_all_10$P_minus_AET_mm))) {
  stop("No finite P − AET values are available for the whole basin and supplied subbasins, 2022–2025.")
}

if (!any(is.finite(wb_subbasin_source_10$AET_over_P_pct))) {
  stop("No finite AET/P values are available for the supplied subbasins, 2022–2025.")
}

# Common y-axis limits make the P − AET magnitude directly comparable across
# the whole basin and all seven subbasins.
pmaet_all_vals_10 <- wb_pmaet_all_10$P_minus_AET_mm[
  is.finite(wb_pmaet_all_10$P_minus_AET_mm)
]
sub_wb_lim_10 <- range(pretty(range(pmaet_all_vals_10), n = 6), finite = TRUE)
sub_wb_breaks_10 <- pretty(sub_wb_lim_10, n = 6)

# AET/P remains a seven-subbasin companion figure, so its limits continue to be
# based only on those seven regional series.
sub_aetp_vals_10 <- wb_subbasin_source_10$AET_over_P_pct[
  is.finite(wb_subbasin_source_10$AET_over_P_pct)
]
sub_aetp_upper_10 <- max(
  150,
  ceiling(max(sub_aetp_vals_10, na.rm = TRUE) / 50) * 50
)
sub_aetp_breaks_10 <- seq(0, sub_aetp_upper_10, by = 50)

sub_panel_theme_10 <- theme_classic(base_size = 10) +
  theme(
    strip.background = element_rect(
      fill = "white",
      colour = "grey55",
      linewidth = 0.45
    ),
    strip.text = element_text(
      size = 9,
      face = "bold",
      hjust = 0
    ),
    panel.border = element_rect(
      colour = "grey65",
      fill = NA,
      linewidth = 0.35
    ),
    panel.grid.major.y = element_line(
      colour = "grey90",
      linewidth = 0.3
    ),
    panel.grid.minor = element_blank(),
    axis.text.x = element_text(
      angle = 35,
      hjust = 1,
      size = 7.5
    ),
    axis.text.y = element_text(size = 7.5),
    axis.title.y = element_text(size = 8.8),
    axis.ticks = element_line(linewidth = 0.3),
    panel.spacing = unit(0.65, "lines"),
    plot.title = element_text(
      face = "bold",
      size = 12,
      hjust = 0
    ),
    plot.subtitle = element_text(
      size = 8.3,
      colour = "grey40",
      hjust = 0
    ),
    plot.caption = element_text(
      size = 7.2,
      colour = "grey40",
      hjust = 0
    ),
    plot.margin = margin(4, 7, 4, 7)
  )

# 10.3a — P − AET across the whole basin and seven supplied subbasins.
p_sub_pmaet_10 <- ggplot(
  wb_pmaet_all_10,
  aes(x = date, y = P_minus_AET_mm)
) +
  geom_hline(yintercept = 0, linewidth = 0.45) +
  geom_col(width = 20, fill = "grey35", na.rm = TRUE) +
  facet_wrap(~ region_label, ncol = 2, scales = "fixed") +
  scale_x_date(
