  ) +
  labs(
    title = "P − AET across the Nechako Basin and seven subbasins during the 2022–2025 drought",
    subtitle = paste0(
      "Whole basin + seven supplied subbasins | monthly values, January 2022–December 2025 | ",
      "AET from ERA5-Land total evaporation"
    ),
    x = NULL,
    y = expression(P - AET~~(mm~month^{-1})),
    caption = paste0(
      "Panel (a) is the whole Nechako Basin; panels (b)–(h) are the seven supplied subbasins. ",
      "P − AET is a water-budget residual diagnostic and is not interpreted as observed runoff."
    )
  ) +
  sub_panel_theme_10

# 10.3b — AET/P across the seven supplied subbasins (unchanged in scope).
p_sub_aetp_10 <- ggplot(
  wb_subbasin_source_10,
