  ) +
  scale_y_continuous(
    limits = c(0, sub_aetp_upper_10),
    breaks = sub_aetp_breaks_10,
    expand = expansion(mult = c(0, 0))
  ) +
  labs(
    title = "Actual evapotranspiration relative to precipitation across Nechako subbasins",
    subtitle = paste0(
      "Seven supplied subbasins | monthly values, January 2022–December 2025 | ",
      "Dashed line = AET equals precipitation (100%)"
    ),
    x = NULL,
    y = "AET / P (%)",
    caption = paste0(
      "AET/P expresses actual evapotranspiration relative to precipitation."
    )
  ) +
  sub_panel_theme_10

for (ext in c("pdf", "png")) {
