    dpi = if (ext == "png") 300 else "print",
    device = ext,
    limitsize = FALSE
  )
  
  cat(sprintf("  ✓ P − AET 8-panel figure written: %s\n", out_pmaet_sub_10))
  cat(sprintf("  ✓ Subbasin AET/P figure written: %s\n", out_aetp_sub_10))
}

cat(
  "  ✓ Regional water-budget companion figures complete: 8-panel P − AET " ,
