suppressPackageStartupMessages({
  library(data.table)
  library(dplyr)
  library(tidyr)
})

MS_REPORT_DIR <- file.path(WD_PATH, "manuscript_reporting")
dir.create(MS_REPORT_DIR, showWarnings = FALSE, recursive = TRUE)

REPORT_ROWS <- list()
add_report_row <- function(section, quantity, value, units = NA_character_,
                           period = NA_character_, source = NA_character_) {
  REPORT_ROWS[[length(REPORT_ROWS) + 1L]] <<- data.frame(
    section = section,
    quantity = quantity,
    value = as.character(value),
    units = units,
    period = period,
    source = source,
    stringsAsFactors = FALSE
  )
}

safe_mean <- function(x) {
  x <- as.numeric(x)
  if (!any(is.finite(x))) return(NA_real_)
  mean(x, na.rm = TRUE)
}

safe_sum <- function(x) {
  x <- as.numeric(x)
  if (!any(is.finite(x))) return(NA_real_)
  sum(x, na.rm = TRUE)
}

safe_round <- function(x, digits = 3L) {
  ifelse(is.finite(x), round(x, digits), NA_real_)
}

safe_min <- function(x) {
  x <- as.numeric(x)
  if (!any(is.finite(x))) return(NA_real_)
  min(x, na.rm = TRUE)
}

safe_max <- function(x) {
  x <- as.numeric(x)
  if (!any(is.finite(x))) return(NA_real_)
  max(x, na.rm = TRUE)
}

date_at_min <- function(x, date) {
  ok <- is.finite(as.numeric(x))
  if (!any(ok)) return(as.Date(NA))
  date[ok][which.min(as.numeric(x)[ok])]
}

date_at_max <- function(x, date) {
  ok <- is.finite(as.numeric(x))
  if (!any(ok)) return(as.Date(NA))
  date[ok][which.max(as.numeric(x)[ok])]
}

# ------------------------------------------------------------------------------
# 11.1 BASIN ANNUAL HYDROCLIMATIC QUANTITIES
# ------------------------------------------------------------------------------

annual_wb <- NULL

WB_ANNUAL_FILE <- file.path(
  WB_DIR,
  "annual_water_budget_1950_2025.csv"
)

if (file.exists(WB_ANNUAL_FILE)) {
  annual_wb <- data.table::fread(WB_ANNUAL_FILE) |>
    as.data.frame()
  
  # 16_climatology_water_budget.R writes one row per region/year.
  # Prefer an explicit whole-basin region where available.
  if (all(c("region_id", "region_name") %in% names(annual_wb))) {
    target_id <- Sys.getenv("NECHAKO_BASIN_REGION_ID", unset = "")
    
    if (nzchar(target_id) && target_id %in% unique(annual_wb$region_id)) {
      annual_wb <- annual_wb[annual_wb$region_id == target_id, , drop = FALSE]
    } else {
      exact_basin <- unique(
        annual_wb[
          grepl(
            "^(Nechako River Basin|Nechako Basin|Whole Nechako Basin|Entire Nechako Basin)$",
            trimws(annual_wb$region_name),
            ignore.case = TRUE
          ),
          c("region_id", "region_name")
        ]
      )
      
      if (nrow(exact_basin) == 1L) {
        annual_wb <- annual_wb[
          annual_wb$region_id == exact_basin$region_id[1],
          ,
          drop = FALSE
        ]
      } else if (data.table::uniqueN(annual_wb$region_id) > 1L) {
        stop(
          "Cannot unambiguously identify the whole-basin row in ",
          WB_ANNUAL_FILE,
          ". Set NECHAKO_BASIN_REGION_ID to the authoritative whole-basin region_id."
        )
      }
    }
  }
  
  annual_wb$year <- as.integer(annual_wb$year)
  
  if (all(c("year", "precipitation_mm", "PET_PM_mm",
            "temperature_degC") %in% names(annual_wb))) {
    
    recent_annual <- annual_wb[
      annual_wb$year >= 2022L & annual_wb$year <= 2025L,
      ,
      drop = FALSE
    ]
    
    # Full-record climatological reference = mean of annual values.
    ref_annual <- annual_wb[
      annual_wb$year >= 1950L & annual_wb$year <= 2025L,
      ,
      drop = FALSE
    ]
    
    ref <- data.frame(
      P_clim_mm = safe_mean(ref_annual$precipitation_mm),
      PET_PM_clim_mm = safe_mean(ref_annual$PET_PM_mm),
      PET_ERA5_clim_mm = if ("PET_ERA5_mm" %in% names(ref_annual))
        safe_mean(ref_annual$PET_ERA5_mm) else NA_real_,
      T_clim_degC = safe_mean(ref_annual$temperature_degC)
    )
    
    hydro_annual <- recent_annual
    
    hydro_annual$P_anomaly_mm <-
      hydro_annual$precipitation_mm - ref$P_clim_mm
    hydro_annual$P_anomaly_pct <-
      100 * hydro_annual$P_anomaly_mm / ref$P_clim_mm
    
    hydro_annual$PET_PM_anomaly_mm <-
      hydro_annual$PET_PM_mm - ref$PET_PM_clim_mm
    hydro_annual$PET_PM_anomaly_pct <-
      100 * hydro_annual$PET_PM_anomaly_mm / ref$PET_PM_clim_mm
    
    if ("PET_ERA5_mm" %in% names(hydro_annual)) {
      hydro_annual$PET_ERA5_anomaly_mm <-
        hydro_annual$PET_ERA5_mm - ref$PET_ERA5_clim_mm
      hydro_annual$PET_ERA5_anomaly_pct <-
        100 * hydro_annual$PET_ERA5_anomaly_mm / ref$PET_ERA5_clim_mm
    } else {
      hydro_annual$PET_ERA5_anomaly_mm <- NA_real_
      hydro_annual$PET_ERA5_anomaly_pct <- NA_real_
    }
    
    hydro_annual$T_anomaly_degC <-
      hydro_annual$temperature_degC - ref$T_clim_degC
    
    hydro_annual <- hydro_annual |>
      select(
        any_of(c(
          "year", "precipitation_mm", "PET_PM_mm", "PET_ERA5_mm",
          "temperature_degC", "P_minus_AET_mm", "P_minus_PET_PM_mm",
          "AET_over_P", "PET_PM_over_P", "AET_over_PET_PM",
          "PET_ERA5_over_P", "residual_runoff_over_P"
        )),
        P_anomaly_mm, P_anomaly_pct,
        PET_PM_anomaly_mm, PET_PM_anomaly_pct,
        PET_ERA5_anomaly_mm, PET_ERA5_anomaly_pct,
        T_anomaly_degC
      )
    
    write.csv(
      hydro_annual,
      file.path(MS_REPORT_DIR, "Table_MS_recent_hydroclimatic_annual.csv"),
      row.names = FALSE
    )
    
    add_report_row(
      "Hydroclimatic evolution",
      "1950-2025 mean annual precipitation",
      safe_round(ref$P_clim_mm, 2), "mm yr-1", "1950-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "1950-2025 mean annual PM-PET",
      safe_round(ref$PET_PM_clim_mm, 2), "mm yr-1", "1950-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "1950-2025 mean annual ERA5-Land PEV",
      safe_round(ref$PET_ERA5_clim_mm, 2), "mm yr-1", "1950-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "1950-2025 mean annual air temperature",
      safe_round(ref$T_clim_degC, 3), "degC", "1950-2025",
      "16_climatology_water_budget.R"
    )
    
    for (yy in recent_annual$year) {
      rr <- hydro_annual[hydro_annual$year == yy, , drop = FALSE]
      if (!nrow(rr)) next
      
      add_report_row(
        "Hydroclimatic evolution",
        paste0("Annual precipitation, ", yy),
        safe_round(rr$precipitation_mm[1], 2), "mm yr-1", as.character(yy),
        "16_climatology_water_budget.R"
      )
      add_report_row(
        "Hydroclimatic evolution",
        paste0("Annual precipitation anomaly, ", yy),
        safe_round(rr$P_anomaly_pct[1], 2), "%", as.character(yy),
        "16_climatology_water_budget.R"
      )
      add_report_row(
        "Hydroclimatic evolution",
        paste0("Annual PM-PET, ", yy),
        safe_round(rr$PET_PM_mm[1], 2), "mm yr-1", as.character(yy),
        "16_climatology_water_budget.R"
      )
      add_report_row(
        "Hydroclimatic evolution",
        paste0("Annual PM-PET anomaly, ", yy),
        safe_round(rr$PET_PM_anomaly_pct[1], 2), "%", as.character(yy),
        "16_climatology_water_budget.R"
      )
      if ("PET_ERA5_mm" %in% names(rr)) {
        add_report_row(
          "Hydroclimatic evolution",
          paste0("Annual ERA5-Land PEV, ", yy),
          safe_round(rr$PET_ERA5_mm[1], 2), "mm yr-1", as.character(yy),
          "16_climatology_water_budget.R"
        )
        add_report_row(
          "Hydroclimatic evolution",
          paste0("Annual ERA5-Land PEV anomaly, ", yy),
          safe_round(rr$PET_ERA5_anomaly_pct[1], 2), "%", as.character(yy),
          "16_climatology_water_budget.R"
        )
      }
      add_report_row(
        "Hydroclimatic evolution",
        paste0("Annual air-temperature anomaly, ", yy),
        safe_round(rr$T_anomaly_degC[1], 3), "degC", as.character(yy),
        "16_climatology_water_budget.R"
      )
    }
    
    # Recent-period aggregate across the four complete annual values.
    recent_mean <- hydro_annual |>
      summarise(
        P_mm = mean(precipitation_mm, na.rm = TRUE),
        PET_PM_mm = mean(PET_PM_mm, na.rm = TRUE),
        PET_ERA5_mm = if ("PET_ERA5_mm" %in% names(hydro_annual))
          mean(PET_ERA5_mm, na.rm = TRUE) else NA_real_,
        T_degC = mean(temperature_degC, na.rm = TRUE),
        P_anom_pct = mean(P_anomaly_pct, na.rm = TRUE),
        PET_PM_anom_pct = mean(PET_PM_anomaly_pct, na.rm = TRUE),
        PET_ERA5_anom_pct = if ("PET_ERA5_anomaly_pct" %in% names(hydro_annual))
          mean(PET_ERA5_anomaly_pct, na.rm = TRUE) else NA_real_,
        T_anom_degC = mean(T_anomaly_degC, na.rm = TRUE)
      )
    
    add_report_row(
      "Hydroclimatic evolution",
      "Mean annual precipitation, 2022-2025",
      safe_round(recent_mean$P_mm, 2), "mm yr-1", "2022-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "Mean annual precipitation anomaly, 2022-2025",
      safe_round(recent_mean$P_anom_pct, 2), "%", "2022-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "Mean annual PM-PET, 2022-2025",
      safe_round(recent_mean$PET_PM_mm, 2), "mm yr-1", "2022-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "Mean annual PM-PET anomaly, 2022-2025",
      safe_round(recent_mean$PET_PM_anom_pct, 2), "%", "2022-2025",
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      "Mean annual air-temperature anomaly, 2022-2025",
      safe_round(recent_mean$T_anom_degC, 3), "degC", "2022-2025",
      "16_climatology_water_budget.R"
    )
  }
}

# ------------------------------------------------------------------------------
# 11.2 MONTHLY RECENT HYDROCLIMATIC EXTREMES
# ------------------------------------------------------------------------------

ANOM_FILE <- file.path(
  WB_DIR,
  "recent_2022_2025_monthly_climatological_anomalies.csv"
)

if (file.exists(ANOM_FILE)) {
  anom_ms <- data.table::fread(ANOM_FILE) |>
    as.data.frame()
  
  if (all(c("date", "precip_anomaly_mm", "pet_PM_anomaly_mm",
            "tair_anomaly_degC") %in% names(anom_ms))) {
    
    if (all(c("region_id", "region_name") %in% names(anom_ms))) {
      target_id <- Sys.getenv("NECHAKO_BASIN_REGION_ID", unset = "")
      if (nzchar(target_id) && target_id %in% unique(anom_ms$region_id)) {
        anom_ms <- anom_ms[anom_ms$region_id == target_id, , drop = FALSE]
      } else {
        exact_basin <- unique(
          anom_ms[
            grepl(
              "^(Nechako River Basin|Nechako Basin|Whole Nechako Basin|Entire Nechako Basin)$",
              trimws(anom_ms$region_name),
              ignore.case = TRUE
            ),
            c("region_id", "region_name")
          ]
        )
        if (nrow(exact_basin) == 1L) {
          anom_ms <- anom_ms[
            anom_ms$region_id == exact_basin$region_id[1],
            ,
            drop = FALSE
          ]
        } else if (data.table::uniqueN(anom_ms$region_id) > 1L) {
          stop(
            "Cannot unambiguously identify the whole-basin row in ",
            ANOM_FILE,
            ". Set NECHAKO_BASIN_REGION_ID."
          )
        }
      }
    }
    
    anom_ms$date <- as.Date(anom_ms$date)
    
    extreme_rows <- list(
      data.frame(
        variable = "Precipitation",
        metric = "minimum anomaly",
        value = safe_min(anom_ms$precip_anomaly_mm),
        date = date_at_min(anom_ms$precip_anomaly_mm, anom_ms$date)
      ),
      data.frame(
        variable = "Precipitation",
        metric = "maximum anomaly",
        value = safe_max(anom_ms$precip_anomaly_mm),
        date = date_at_max(anom_ms$precip_anomaly_mm, anom_ms$date)
      ),
      data.frame(
        variable = "PM-PET",
        metric = "minimum anomaly",
        value = safe_min(anom_ms$pet_PM_anomaly_mm),
        date = date_at_min(anom_ms$pet_PM_anomaly_mm, anom_ms$date)
      ),
      data.frame(
        variable = "PM-PET",
        metric = "maximum anomaly",
        value = safe_max(anom_ms$pet_PM_anomaly_mm),
        date = date_at_max(anom_ms$pet_PM_anomaly_mm, anom_ms$date)
      ),
      data.frame(
        variable = "Air temperature",
        metric = "minimum anomaly",
        value = safe_min(anom_ms$tair_anomaly_degC),
        date = date_at_min(anom_ms$tair_anomaly_degC, anom_ms$date)
      ),
      data.frame(
        variable = "Air temperature",
        metric = "maximum anomaly",
        value = safe_max(anom_ms$tair_anomaly_degC),
        date = date_at_max(anom_ms$tair_anomaly_degC, anom_ms$date)
      )
    )
    
    if ("pet_ERA5_anomaly_mm" %in% names(anom_ms)) {
      extreme_rows <- c(
        extreme_rows,
        list(
          data.frame(
            variable = "ERA5-Land PEV",
            metric = "minimum anomaly",
            value = safe_min(anom_ms$pet_ERA5_anomaly_mm),
            date = date_at_min(anom_ms$pet_ERA5_anomaly_mm, anom_ms$date)
          ),
          data.frame(
            variable = "ERA5-Land PEV",
            metric = "maximum anomaly",
            value = safe_max(anom_ms$pet_ERA5_anomaly_mm),
            date = date_at_max(anom_ms$pet_ERA5_anomaly_mm, anom_ms$date)
          )
        )
      )
    }
    
    extremes <- dplyr::bind_rows(extreme_rows)
    
    write.csv(
      extremes,
      file.path(MS_REPORT_DIR, "Table_MS_recent_hydroclimatic_monthly_extremes.csv"),
      row.names = FALSE
    )
    
    for (i in seq_len(nrow(extremes))) {
      add_report_row(
        "Hydroclimatic evolution",
        paste(extremes$variable[i], extremes$metric[i]),
        safe_round(extremes$value[i], 3),
        if (extremes$variable[i] == "Air temperature") "degC" else "mm month-1",
        format(extremes$date[i], "%Y-%m"),
        "16_climatology_water_budget.R"
      )
    }
  }
}

# ------------------------------------------------------------------------------
# 11.3 WARM-SEASON HYDROCLIMATIC QUANTITIES
# ------------------------------------------------------------------------------
# The manuscript uses MJJAS for the warm-season PET/sensitivity analyses.
# This block therefore reports MJJAS annual totals/means directly from the
# authoritative 16 monthly climate-water-budget output and compares each
# year's MJJAS values with the corresponding 1950-2025 calendar-month
# climatology. No PET or drought index is recomputed.

MONTHLY_WB_FILE <- file.path(
  WB_DIR,
  "recent_2022_2025_monthly_climate_water_budget.csv"
)
MONTHLY_CLIM_FILE <- file.path(
  WB_DIR,
  "climatology_monthly_1950_2025.csv"
)

if (file.exists(MONTHLY_WB_FILE) && file.exists(MONTHLY_CLIM_FILE)) {
  
  recent_monthly_wb <- data.table::fread(MONTHLY_WB_FILE) |>
    as.data.frame()
  monthly_clim_wb <- data.table::fread(MONTHLY_CLIM_FILE) |>
    as.data.frame()
  
  select_whole_basin <- function(df, file_label) {
    if (!all(c("region_id", "region_name") %in% names(df))) return(df)
    
    target_id <- Sys.getenv("NECHAKO_BASIN_REGION_ID", unset = "")
    
    if (nzchar(target_id) && target_id %in% unique(df$region_id)) {
      return(df[df$region_id == target_id, , drop = FALSE])
    }
    
    exact_basin <- unique(
      df[
        grepl(
          "^(Nechako River Basin|Nechako Basin|Whole Nechako Basin|Entire Nechako Basin)$",
          trimws(df$region_name),
          ignore.case = TRUE
        ),
        c("region_id", "region_name")
      ]
    )
    
    if (nrow(exact_basin) == 1L) {
      return(df[df$region_id == exact_basin$region_id[1], , drop = FALSE])
    }
    
    if (data.table::uniqueN(df$region_id) == 1L) return(df)
    
    stop(
      "Cannot unambiguously identify the whole-basin row in ",
      file_label,
      ". Set NECHAKO_BASIN_REGION_ID."
    )
  }
  
  recent_monthly_wb <- select_whole_basin(
    recent_monthly_wb,
    MONTHLY_WB_FILE
  )
  monthly_clim_wb <- select_whole_basin(
    monthly_clim_wb,
    MONTHLY_CLIM_FILE
  )
  
  recent_monthly_wb$date <- as.Date(recent_monthly_wb$date)
  recent_monthly_wb$year <- as.integer(
    if ("year" %in% names(recent_monthly_wb))
      recent_monthly_wb$year
    else format(recent_monthly_wb$date, "%Y")
  )
  recent_monthly_wb$month <- as.integer(
    if ("month" %in% names(recent_monthly_wb))
      recent_monthly_wb$month
    else format(recent_monthly_wb$date, "%m")
  )
  
  monthly_clim_wb$month <- as.integer(monthly_clim_wb$month)
  
  recent_warm <- recent_monthly_wb |>
    filter(month %in% 5:9)
  
  clim_warm <- monthly_clim_wb |>
    filter(month %in% 5:9)
  
  # The climatological MJJAS reference is the sum of the five monthly
  # calendar means for depth variables and the mean of the five monthly
  # climatological temperatures.
  warm_ref <- list(
    P = safe_sum(clim_warm$precipitation_mm),
    PM = safe_sum(clim_warm$PET_PM_mm),
    E5 = if ("PET_ERA5_mm" %in% names(clim_warm))
      safe_sum(clim_warm$PET_ERA5_mm) else NA_real_,
    T = safe_mean(clim_warm$temperature_degC)
  )
  
  has_recent_era5 <- "pet_era5_mm_month" %in% names(recent_warm)
  
  warm_annual <- recent_warm |>
    group_by(year) |>
    summarise(
      P_MJJAS_mm = safe_sum(precip_mm_month),
      PM_PET_MJJAS_mm = safe_sum(pet_mm_month),
      ERA5_PEV_MJJAS_mm =
        if (has_recent_era5) safe_sum(pet_era5_mm_month) else NA_real_,
      T_MJJAS_degC = safe_mean(tair_degC_month),
      .groups = "drop"
    )
  
  warm_annual$P_anomaly_mm <-
    warm_annual$P_MJJAS_mm - warm_ref$P
  warm_annual$P_anomaly_pct <-
    100 * warm_annual$P_anomaly_mm / warm_ref$P
  
  warm_annual$PM_PET_anomaly_mm <-
    warm_annual$PM_PET_MJJAS_mm - warm_ref$PM
  warm_annual$PM_PET_anomaly_pct <-
    100 * warm_annual$PM_PET_anomaly_mm / warm_ref$PM
  
  if (all(is.finite(warm_annual$ERA5_PEV_MJJAS_mm)) &&
      is.finite(warm_ref$E5)) {
    warm_annual$ERA5_PEV_anomaly_mm <-
      warm_annual$ERA5_PEV_MJJAS_mm - warm_ref$E5
    warm_annual$ERA5_PEV_anomaly_pct <-
      100 * warm_annual$ERA5_PEV_anomaly_mm / warm_ref$E5
  } else {
    warm_annual$ERA5_PEV_anomaly_mm <- NA_real_
    warm_annual$ERA5_PEV_anomaly_pct <- NA_real_
  }
  
  warm_annual$T_anomaly_degC <-
    warm_annual$T_MJJAS_degC - warm_ref$T
  
  write.csv(
    warm_annual,
    file.path(MS_REPORT_DIR, "Table_MS_recent_hydroclimatic_warmseason.csv"),
    row.names = FALSE
  )
  
  add_report_row(
    "Hydroclimatic evolution",
    "MJJAS climatological precipitation",
    safe_round(warm_ref$P, 2), "mm", "1950-2025",
    "16_climatology_water_budget.R"
  )
  add_report_row(
    "Hydroclimatic evolution",
    "MJJAS climatological PM-PET",
    safe_round(warm_ref$PM, 2), "mm", "1950-2025",
    "16_climatology_water_budget.R"
  )
  add_report_row(
    "Hydroclimatic evolution",
    "MJJAS climatological air temperature",
    safe_round(warm_ref$T, 3), "degC", "1950-2025",
    "16_climatology_water_budget.R"
  )
  
  for (i in seq_len(nrow(warm_annual))) {
    rr <- warm_annual[i, ]
    
    add_report_row(
      "Hydroclimatic evolution",
      paste0("MJJAS precipitation anomaly, ", rr$year),
      safe_round(rr$P_anomaly_pct, 2), "%", as.character(rr$year),
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      paste0("MJJAS PM-PET anomaly, ", rr$year),
      safe_round(rr$PM_PET_anomaly_pct, 2), "%", as.character(rr$year),
      "16_climatology_water_budget.R"
    )
    add_report_row(
      "Hydroclimatic evolution",
      paste0("MJJAS air-temperature anomaly, ", rr$year),
      safe_round(rr$T_anomaly_degC, 3), "degC", as.character(rr$year),
      "16_climatology_water_budget.R"
    )
  }
}

# ------------------------------------------------------------------------------
# 11.4 SW08 EVENT-RANKING VALUES FOR THE MANUSCRIPT
# ------------------------------------------------------------------------------
# ------------------------------------------------------------------------------

if (exists("sw08_catalog_ms") && nrow(sw08_catalog_ms)) {
  
  event_report <- sw08_catalog_ms |>
    as.data.frame() |>
    mutate(
      index = case_when(
        grepl("^spei_era5_", index_label, ignore.case = TRUE) ~ "SPEI-ERA5",
        grepl("^spei_", index_label, ignore.case = TRUE) ~ "SPEI-PM",
        grepl("^spi_", index_label, ignore.case = TRUE) ~ "SPI",
        TRUE ~ index_label
      ),
      scale_months = as.integer(sub(".*_([0-9]+)$", "\\1", index_label)),
      start_date = as.Date(start_date),
      end_date = as.Date(end_date)
    ) |>
    filter(
      scale_months %in% c(1L, 3L, 6L, 12L, 24L, 36L)
    )
  
  # Recent primary event by index and scale.
  recent_primary_report <- event_report |>
    filter(is_recent %in% TRUE) |>
    group_by(index, scale_months) |>
    slice_max(severity, n = 1L, with_ties = FALSE) |>
    ungroup() |>
    arrange(index, scale_months)
  
  event_report_out <- recent_primary_report |>
    transmute(
      index,
      scale_months,
      start_date,
      end_date,
      duration_months,
      duration_class,
      mean_intensity = mean_int,
      severity,
      rank_by_severity,
      return_period_years,
      percentile_rank
    )
  
  write.csv(
    event_report_out,
    file.path(MS_REPORT_DIR, "Table_MS_event_reporting.csv"),
    row.names = FALSE
  )
  
  for (i in seq_len(nrow(event_report_out))) {
    rr <- event_report_out[i, ]
    
    add_report_row(
      "Drought event ranking",
      paste0(rr$index, "-", rr$scale_months, " recent primary-event severity"),
      safe_round(rr$severity, 4), "severity",
      paste0(rr$start_date, " to ", rr$end_date),
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      paste0(rr$index, "-", rr$scale_months, " recent primary-event duration"),
      rr$duration_months, "months",
      paste0(rr$start_date, " to ", rr$end_date),
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      paste0(rr$index, "-", rr$scale_months, " recent primary-event historical rank"),
      rr$rank_by_severity, "rank",
      "1950-2025",
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      paste0(rr$index, "-", rr$scale_months, " recent primary-event percentile"),
      safe_round(rr$percentile_rank, 2), "percentile",
      "1950-2025",
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      paste0(rr$index, "-", rr$scale_months, " recent primary-event return period"),
      safe_round(rr$return_period_years, 2), "years",
      "1950-2025",
      "9event_ranking.R"
    )
  }
  
  # Explicit 2023 SPEI-3 event used in the manuscript narrative.
  target_2023 <- event_report |>
    filter(
      index == "SPEI-PM",
      scale_months == 3L,
      start_date == as.Date("2023-05-01"),
      end_date == as.Date("2023-12-01")
    )
  
  if (nrow(target_2023) == 1L) {
    rr <- target_2023[1, ]
    
    add_report_row(
      "Drought event ranking",
      "May-December 2023 SPEI-3 event severity",
      safe_round(rr$severity, 4), "severity",
      "2023-05 to 2023-12",
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      "May-December 2023 SPEI-3 event rank",
      rr$rank_by_severity, "rank",
      "1950-2025",
      "9event_ranking.R"
    )
    add_report_row(
      "Drought event ranking",
      "Qualifying historical SPEI-3 event count",
      sum(event_report$index == "SPEI-PM" & event_report$scale_months == 3L),
      "events",
      "1950-2025",
      "9event_ranking.R"
    )
  }
  
  # Annual 2023 threshold persistence from the authoritative basin series.
  spei3_ts <- find_basin_series(c("spei"), 3L)
  
  if (!is.null(spei3_ts) && nrow(spei3_ts)) {
    n_below_2023 <- sum(
      spei3_ts$date >= as.Date("2023-01-01") &
        spei3_ts$date <= as.Date("2023-12-01") &
        spei3_ts$value < -0.5,
      na.rm = TRUE
    )
    
    add_report_row(
      "Drought event ranking",
      "SPEI-3 months below -0.5 during 2023",
      n_below_2023, "months", "2023",
      "7basin_timeseries.R / authoritative basin-average SPEI-3"
    )
  }
}

# ------------------------------------------------------------------------------
# 11.5 PET-PRODUCT AGREEMENT VALUES
# ------------------------------------------------------------------------------

if (file.exists(PET_AGREE_CSV)) {
  agree_report <- data.table::fread(PET_AGREE_CSV) |>
    as.data.frame() |>
    mutate(scale = as.integer(scale))
  
  keep_periods <- c(
    "Full record",
    "2022-2025",
    "Drought-active",
    "2022-2025 drought-active"
  )
  
  agree_report <- agree_report |>
    filter(
      scale %in% c(1L, 3L, 6L, 12L, 24L, 36L),
      period %in% keep_periods
    ) |>
    arrange(scale, factor(period, levels = keep_periods))
  
  write.csv(
    agree_report,
    file.path(MS_REPORT_DIR, "Table_MS_PET_agreement_reporting.csv"),
    row.names = FALSE
  )
  
  for (i in seq_len(nrow(agree_report))) {
    rr <- agree_report[i, ]
    
    add_report_row(
      "PET-product sensitivity",
      paste0("Pearson r, scale ", rr$scale),
      safe_round(rr$pearson_r, 4), "r", rr$period,
      "12PET_formulation_sensitivity.R"
    )
    add_report_row(
      "PET-product sensitivity",
      paste0("RMSE, scale ", rr$scale),
      safe_round(rr$rmse, 4), "SPEI units", rr$period,
      "12PET_formulation_sensitivity.R"
    )
    add_report_row(
      "PET-product sensitivity",
      paste0("Drought-state agreement, scale ", rr$scale),
      safe_round(rr$drought_state_agreement_pct, 2), "%",
      rr$period, "12PET_formulation_sensitivity.R"
    )
    add_report_row(
      "PET-product sensitivity",
      paste0("Mean absolute delta SPEI, scale ", rr$scale),
      safe_round(rr$mean_abs_delta_spei, 4), "SPEI units",
      rr$period, "12PET_formulation_sensitivity.R"
    )
    add_report_row(
      "PET-product sensitivity",
      paste0("Mean signed delta SPEI, scale ", rr$scale),
      safe_round(rr$mean_delta_spei, 4), "SPEI units",
      rr$period, "12PET_formulation_sensitivity.R"
    )
  }
}

# ------------------------------------------------------------------------------
# 11.6 SHAPLEY VALUES AND NUMERICAL CLOSURE
# ------------------------------------------------------------------------------

SHAPLEY_SUMMARY_FILE <- file.path(
  WD_PATH,
  "pet_sensitivity",
  "shapley",
  "PET_PM_Shapley_summary.csv"
)

SHAPLEY_MONTHLY_FILE <- file.path(
  WD_PATH,
  "pet_sensitivity",
  "shapley",
  "PET_PM_Shapley_monthly.csv"
)

if (file.exists(SHAPLEY_SUMMARY_FILE)) {
  shapley_report <- data.table::fread(SHAPLEY_SUMMARY_FILE) |>
    as.data.frame() |>
    mutate(
      component = as.character(component),
      period = as.character(period)
    )
  
  write.csv(
    shapley_report,
    file.path(MS_REPORT_DIR, "Table_MS_Shapley_reporting.csv"),
    row.names = FALSE
  )
  
  for (i in seq_len(nrow(shapley_report))) {
    rr <- shapley_report[i, ]
    
    add_report_row(
      "PM-PET Shapley attribution",
      paste0(rr$component, " mean Shapley allocation"),
      safe_round(rr$mean_phi_mm_d, 6), "mm day-1", rr$period,
      "15PET_shapley_decomposition.R"
    )
  }
}

if (file.exists(SHAPLEY_MONTHLY_FILE)) {
  shapley_monthly <- data.table::fread(SHAPLEY_MONTHLY_FILE) |>
    as.data.frame()
  
  if ("shapley_closure_error_mm_d" %in% names(shapley_monthly)) {
    max_closure <- max(
      abs(as.numeric(shapley_monthly$shapley_closure_error_mm_d)),
      na.rm = TRUE
    )
    
    add_report_row(
      "PM-PET Shapley attribution",
      "Maximum absolute monthly Shapley closure error",
      format(max_closure, scientific = TRUE, digits = 6),
      "mm day-1", "1950-2025",
      "15PET_shapley_decomposition.R"
    )
  }
  
  # Direct recent warm-season PM-PET anomaly from the monthly Shapley table.
  if (all(c("date", "pm_pet_anomaly_mm_d") %in% names(shapley_monthly))) {
    shapley_monthly$date <- as.Date(shapley_monthly$date)
    
    warm_recent <- shapley_monthly[
      shapley_monthly$date >= as.Date("2022-05-01") &
        shapley_monthly$date <= as.Date("2025-09-01"),
      ,
      drop = FALSE
    ]
    
    if (nrow(warm_recent)) {
      add_report_row(
        "PM-PET Shapley attribution",
        "Mean PM-PET anomaly, 2022-2025 warm season",
        safe_round(safe_mean(warm_recent$pm_pet_anomaly_mm_d), 6),
        "mm day-1", "2022-2025 warm season",
        "15PET_shapley_decomposition.R"
      )
    }
  }
}

# ------------------------------------------------------------------------------
# 11.7 BASIN TREND VALUES FROM AUTHORITATIVE 4pr OUTPUT
# ------------------------------------------------------------------------------

ALL_RESULTS_FILE <- file.path(
  WD_PATH,
  "trend_analysis_pr_pet",
  "all_results.rds"
)

if (file.exists(ALL_RESULTS_FILE)) {
  all_results_ms <- tryCatch(
    readRDS(ALL_RESULTS_FILE),
    error = function(e) NULL
  )
  
  if (!is.null(all_results_ms) && nrow(all_results_ms)) {
    trend_basin <- as.data.frame(all_results_ms) |>
      filter(
        is_basin_average %in% TRUE,
        period == "annual",
        variable %in% c("Precipitation", "PET", "PET_ERA5", "Temperature")
      ) |>
      transmute(
        variable,
        tau_vc,
        p_value_vc,
        sl_vc,
        tau_tfpw,
        p_value_tfpw,
        sl_tfpw,
        changepoint_detected,
        first_changepoint_year,
        magnitude_shift
      )
    
    write.csv(
      trend_basin,
      file.path(MS_REPORT_DIR, "Table_MS_basin_trends_reporting.csv"),
      row.names = FALSE
    )
    
    for (i in seq_len(nrow(trend_basin))) {
      rr <- trend_basin[i, ]
      
      add_report_row(
        "Long-term hydroclimatic context",
        paste0(rr$variable, " annual TFPW tau"),
        safe_round(rr$tau_tfpw, 4), "Kendall tau", "1950-2025",
        "4pr_pet_trends.r / all_results.rds"
      )
      add_report_row(
        "Long-term hydroclimatic context",
        paste0(rr$variable, " annual TFPW p-value"),
        safe_round(rr$p_value_tfpw, 6), "p", "1950-2025",
        "4pr_pet_trends.r / all_results.rds"
      )
      add_report_row(
        "Long-term hydroclimatic context",
        paste0(rr$variable, " annual TFPW Sen slope"),
        safe_round(rr$sl_tfpw, 6), "native units yr-1", "1950-2025",
        "4pr_pet_trends.r / all_results.rds"
      )
      if (isTRUE(rr$changepoint_detected)) {
        add_report_row(
          "Long-term hydroclimatic context",
          paste0(rr$variable, " first detected changepoint"),
          rr$first_changepoint_year, "year", "1950-2025",
          "4pr_pet_trends.r / all_results.rds"
        )
      }
    }
  }
}

# ------------------------------------------------------------------------------
# 11.8 WRITE MASTER MACHINE-READABLE REPORT
# ------------------------------------------------------------------------------

if (length(REPORT_ROWS)) {
  manuscript_numeric_results <- dplyr::bind_rows(REPORT_ROWS)
  
  write.csv(
    manuscript_numeric_results,
    file.path(MS_REPORT_DIR, "Manuscript_numeric_results.csv"),
    row.names = FALSE
  )
  
  # Human-readable text file: only values actually available from authoritative
  # upstream outputs are written. Missing upstream products are not guessed.
  txt_path <- file.path(MS_REPORT_DIR, "Manuscript_numeric_results.txt")
  
  con <- file(txt_path, open = "wt", encoding = "UTF-8")
  on.exit(close(con), add = TRUE)
  
  writeLines(
    c(
      "NECHAKO 2022–2025 MANUSCRIPT NUMERIC RESULTS",
      "Generated by 11nechako_drought_manuscript.R",
      "",
      "Only values available from authoritative upstream outputs are reported.",
      "PET-PM versus PET-ERA5 is a product/formulation sensitivity diagnostic.",
      "Shapley values are model-level allocations within FAO-56 PM.",
      ""
    ),
    con
  )
  
  for (sec in unique(manuscript_numeric_results$section)) {
    writeLines(c(paste0("[", sec, "]")), con)
    
    z <- manuscript_numeric_results[
      manuscript_numeric_results$section == sec,
      ,
      drop = FALSE
    ]
    
    for (i in seq_len(nrow(z))) {
      line <- paste0(
        "- ", z$quantity[i],
        ": ", z$value[i],
        if (is.finite(suppressWarnings(as.numeric(z$value[i]))) &&
            !is.na(z$units[i]) && nzchar(z$units[i]))
          paste0(" ", z$units[i]) else "",
        if (!is.na(z$period[i]) && nzchar(z$period[i]))
          paste0(" [", z$period[i], "]") else "",
        " {", z$source[i], "}"
      )
      writeLines(line, con)
    }
    
    writeLines("", con)
  }
  
  cat(
    "\n============================================================\n",
    " SECTION 11: MANUSCRIPT NUMERIC-RESULTS EXTRACTION COMPLETE\n",
    "============================================================\n",
    sprintf(
      "  ✓ %d numeric reporting rows written.\n",
      nrow(manuscript_numeric_results)
    ),
    "  ✓ Manuscript_numeric_results.csv\n",
    "  ✓ Manuscript_numeric_results.txt\n",
    "  ✓ Supporting manuscript reporting tables\n",
    sprintf("  Output directory: %s\n", normalizePath(MS_REPORT_DIR)),
    "============================================================\n",
    sep = ""
  )
} else {
  cat(
    "\n[SKIP] Section 11: no authoritative upstream numeric products were available.\n"
  )
}

